48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        validateRequiredFields(ownerFieldsDto);
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        this.clinicService.saveOwner(owner);
109	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
110	        headers.setLocation(UriComponentsBuilder.newInstance()
111	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
112	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
113	    }
114	
115	    /**
116	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
117	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
118	     * so the client receives a 400 whose {@code errors} array lists each missing field.
119	     *
120	     * @param ownerFieldsDto the submitted owner fields
121	     */
122	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
123	        List<String> missingFields = new ArrayList<>();
124	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
131	            missingFields.add("address");
132	        }
133	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new MissingOwnerFieldsException(missingFields);
141	        }
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
147	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
148	        if (currentOwner == null) {
149	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
150	        }
151	        currentOwner.setAddress(ownerFieldsDto.getAddress());
152	        currentOwner.setCity(ownerFieldsDto.getCity());
153	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
154	        currentOwner.setLastName(ownerFieldsDto.getLastName());
155	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
156	        this.clinicService.saveOwner(currentOwner);
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        this.clinicService.deleteOwner(owner);
169	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        HttpHeaders headers = new HttpHeaders();
180	        Pet pet = petMapper.toPet(petFieldsDto);
181	        owner.setId(ownerId);
182	        pet.setOwner(owner);
183	        pet.getType().setName(null);
184	        this.clinicService.savePet(pet);
185	        PetDto petDto = petMapper.toPetDto(pet);
186	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
187	            .buildAndExpand(pet.getId()).toUri());
188	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner != null) {
196	            Pet currentPet = this.clinicService.findPetById(petId);
197	            if (currentPet != null) {
198	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
199	                currentPet.setName(petFieldsDto.getName());
200	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
201	                this.clinicService.savePet(currentPet);
202	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
211	        HttpHeaders headers = new HttpHeaders();
212	        Visit visit = visitMapper.toVisit(visitFieldsDto);
213	        Pet pet = new Pet();
214	        pet.setId(petId);
215	        visit.setPet(pet);
216	        this.clinicService.saveVisit(visit);
217	        VisitDto visitDto = visitMapper.toVisitDto(visit);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
219	            .buildAndExpand(visit.getId()).toUri());
220	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
221	    }
222	
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner != null) {
229	            Pet pet = owner.getPet(petId);
230	            if (pet != null) {
231	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	}
